"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["7148"],{3173(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>h,frontMatter:()=>a,contentTitle:()=>s,toc:()=>c,assets:()=>l});var o=JSON.parse('{"id":"reference/reports/howtos/createlinkutilizationreport","title":"How to Work With and Create Link Utilization Reports","description":"alms \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/reports/howtos/createlinkutilizationreport.md","sourceDirName":"reference/reports/howtos","slug":"/reference/reports/howtos/createlinkutilizationreport","permalink":"/personal-av-docs/docs/reference/reports/howtos/createlinkutilizationreport","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/reports/howtos/createlinkutilizationreport.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to Work With and Create Link Utilization Reports","sidebar_label":"How to Work With and Create Link Utiliza","sidebar_position":99,"edition":"alms","source":"https://doc.airvantage.net/alms/reference/reports/howtos/createlinkutilizationreport","format":"md"}}'),r=n(4848),i=n(8453);let a={title:"How to Work With and Create Link Utilization Reports",sidebar_label:"How to Work With and Create Link Utiliza",sidebar_position:99,edition:"alms",source:"https://doc.airvantage.net/alms/reference/reports/howtos/createlinkutilizationreport",format:"md"},s,l={},c=[];function d(e){let t={a:"a",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsxs)(t.p,{children:[":::note Edition\n",(0,r.jsx)(t.strong,{children:"alms"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,r.jsx)(t.a,{href:"https://doc.airvantage.net/alms/reference/reports/howtos/createlinkutilizationreport",children:"Original page"}),".\n:::"]}),"\n",(0,r.jsx)(t.p,{children:"How to Work With and Create Link Utilization Reports\nLink Utilization\nThe Link Utilization report shows you details of WAN connectivity over time, and helps you identify systems that are not configured or operating correctly. This report is best used for a small number of systems and is ideal for identifying connectivity issues that occur at specific times of day. The time range is divided into segments, each displaying periods of network connectivity state.\nThe report displays the following values:\nSystem Name\nTime Range\nCellular interface(s), including Cellular, LPWA and external modem/HPUE (if connected)\nCarrier Name\nUptime Percentage\nData Usage\nThis report applies only to systems running AirLink OS.\nAs mentioned above, the Link Utilization report is intended to identify systems that are problematic, based on the report parameters. Semtech recommends configuring this report to display only systems that are operating beneath your performance expectations. Ideally, a properly configured Link Utilization report will return only a few (but nevertheless important) results.\nConversely, you may also want to use the Link Utilization report to get a picture of your fleet (or, ideally, a subset of your fleet) under normal operating conditions, and establish a baseline. In that case, Sierra Wireless recommends configuring the report using the default report properties (for example, leaving\nUptime %\n,\nTraffic greater than\n, and\nShutdown Event Type\nfilters at default).\nViewing a Link Utilization Report\nThe scrolling area under the main report shows a condensed view of the main report. Click and drag the horizontal scroll bar to move within the report timeline, and drag the \u201Csizing bars\u201D to zoom in or out.\nThe color key along the bottom of the report shows you the possible statuses.\nYou can change the display and perform other actions using the buttons along the top of the report.\nExpand All\n: Expands the view to show all WAN interfaces for the displayed systems. Click again to collapse the expanded view.\nPage\n: For reports with over 20 systems, use the Page buttons to view Link Utilization information for additional systems.\nFull Screen\n: Expands the report to the full width of the browser window\nDownload PDF\n: Saves the current report view as a PDF.\nHover over any segment to view details.\nClicking a segment displays a page showing the events for that segment, and the location of the system.\nFiltering Report Results\nYou can fine-tune your report results with the filters shown below.\nClick\nto clear filters.\nFILTER\nDESCRIPTION\nEXAMPLE\nSystems\nSelect one or more systems\nLink Status\nSelect a link status to display\nUptime\nSelect the interfaces that have had the least (or most) uptime. This can help you locate systems that might be having connectivity issues.\nLink Name\nSelect specific interfaces for the selected systems\nCreating a Link Utilization Report\nTo begin, from the Reporting dashboard, click the\nCreate a New Report\nicon.\nAn empty report screen appears.\nSelect a Template\nChoose how often you\u2019d like this report to be run.\nClick:\nSingle\nfor a one-time report\nWeekly\nMonthly\nYearly\nUnder\nReport Properties\n, you can complete the scheduling for your new report. The section below describes how to configure the time and the day on which you\u2019d like your report to run.\nTo run a report immediately, click\nRun Report\n.\nDefine the Report Properties\nThe required fields for creating a valid report are\nType\n,\nName\nand\nRange\n.\nSelect the Report Type\nSelect\nLink Utilization\nfrom the\nType\nmenu.\nEnter a Name and Description\nGive your report a brief, descriptive name. You may want to use the AirLink gateway or router model or serial number.\nBelow the\nName\nfield, you can enter a longer report description. You may want to include the report\u2019s schedule and reporting zone.\nSelect the Reporting Range\nThe Range menu lists the options for the reporting period. You can select a predefined Reporting Range, or configure a Custom range.\nIf scheduling a recurring report, select one of the relative date ranges (\nYesterday\nor\nLast 7 Days\n, for  example). Selecting an absolute range will generate the same results each time.\nIf you click\nCustom\n, a calendar appears, allowing you to select a start date/time and an end date/time for your report.\nSelect Recipient Email Addresses\nClick the\nRecipient Emails\nfield to select the people you would like to be notified when the report is run.\nYou can also manually enter email addresses in this field.\nSelect Which Interfaces to Include\nUse this option to filter out inactive interfaces and run the report only for interfaces that have been passing traffic.\nThe default value is Yes. If you select No, the generated report will include all WAN interfaces available on a router. A report that includes all interfaces may be useful to identify and troubleshooting inactive interfaces on similarly configured gateways.\nSelect Uptime Percentage\nUse this option to include interfaces that have an uptime less than the entered value. The uptime percentage is defined as time online against time powered up.\nThe default value is 95%. Select a lower value if tolerance of the stability of a certain interface is high. A lower value may help you identify and troubleshoot unstable WAN interfaces.\nSelect Traffic Size\nUse this option to filter out interfaces that have passed less traffic than the entered value.\nThe default value is 50 MB. If the value is 0, all WAN interfaces will be included in the report. A higher value may help you identify WAN interfaces that have consumed an unexpected amount of data during the report period.\nSelect Shutdown Event Type\nFilter the report based on the following shutdown event types:\nAll (default value)\nClean Shutdown\nUnclean Shutdown\nA \u201CClean Shutdown\u201D event is when a router shuts down as expected. An \u201CUnclean Shutdown\u201D event is when a router shuts down unexpectedly. When \u201CClean Shutdown\u201D is selected, Shutdown Events in the report will include only \u201CClean Shutdown\u201D events. When \u201CUnclean Shutdown\u201D is selected, Shutdown Events in the report will include only unexpected shutdown events.\nSelect the Systems\nSelect the systems for which you want to run your new report. Select checkboxes for the desired system(s), or filter the list to narrow down your choices. You do not need to use the checkboxes to select specific systems. Selecting the checkboxes will override general filters.\nSelect Advanced Settings: Start and End Dates\nThe Advanced settings are strictly optional. If you enable these settings, you may want to set a reminder (external to ALMS) to notify yourself of the start and end dates.\nClick the\nAdvanced\nbutton to display options for selecting start and end dates for your reports. For example, you can configure a weekly report to run for two months starting one week from today.\nClicking\nStart Time\nor\nRun Until\ndisplays a calendar on which you can define a start date/time and end date/time."})]})}function h(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>a,x:()=>s});var o=n(6540);let r={},i=o.createContext(r);function a(e){let t=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:a(e.components),o.createElement(i.Provider,{value:t},e.children)}}}]);